def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_def = opp.count('D')
    my_def = me.count('D')
    last_opp = opp[-1]

    if opp_def == 0:
        return 'C'
    if opp_def == n:
        return 'D'

    recent = opp[-10:] if n >= 10 else opp
    recent_opp_def = recent.count('D')

    if last_opp == 'D':
        if recent_opp_def <= 2:
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            if rng.random() < 0.8:
                return 'C'
        if recent_opp_def >= 4:
            return 'D'
        return 'D'

    if n >= 3 and opp[-3:].count('C') >= 2:
        return 'C'

    if recent_opp_def >= 4:
        return 'D'

    if recent_opp_def >= 2:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    return 'C'
